// Datos que manda el panel de radicación comercial al confirmar.
const b = $input.first().json.body || {};
const CONFIG = {
  // Carpeta PROCESAMIENTO COMERCIAL (Operaciones). La cuenta de la credencial de Drive debe poder editarla.
  CARPETA_RAIZ_ID: '1V7lauqGk3uUFkCi6Q9NWu-MeZiah5gNS'
};
const limpio = (s) => String(s || '').replace(/[\\/:*?"<>|]+/g, ' ').replace(/\s+/g, ' ').trim();
const cliente = b.cliente || {};
const nombreCliente = limpio(cliente.razonSocial) || ('NIT ' + String(cliente.nit || '').replace(/\D/g, ''));
if (!nombreCliente || nombreCliente === 'NIT ') throw new Error('La radicación no trae el cliente.');
// Diferenciador: fecha y hora de creación (hora Colombia), para que Karen identifique la carpeta y luego le ponga el número.
const ahora = new Date().toLocaleString('sv-SE', { timeZone: 'America/Bogota' }); // "2026-10-20 13:45:07"
const nombreCarpeta = nombreCliente + ' - ' + ahora.slice(0, 10) + ' ' + ahora.slice(11, 13) + 'h' + ahora.slice(14, 16);
const pagadores = (Array.isArray(b.pagadores) ? b.pagadores : []).filter(p => p && (p.razonSocial || p.nit));
// Mapeo (estructura de Producto, correo de Álvaro 27-oct): las facturas seleccionadas se leen completas de opportunity_mapping.
const m = b.mapeo || {};
const soloNit = (v) => String(v || '').replace(/\D/g, '');
const facturasSel = (Array.isArray(m.facturas) ? m.facturas : []).map(f => ({
  cufe: String(f.cufe || '').replace(/[^0-9A-Za-z]/g, ''),
  numeroFactura: String(f.numeroFactura || '').replace(/[^0-9A-Za-z-]/g, ''),
  nitPagador: soloNit(f.nitPagador)
})).filter(f => f.cufe || f.numeroFactura);
const nitEmisor = soloNit(m.nitEmisor || cliente.nit);
const mapeoSel = facturasSel.length && nitEmisor ? { nitEmisor, fechaPago: String(m.fechaAproximadaPago || ''), facturas: facturasSel } : null;
const lista = (vals) => vals.length ? vals.map(v => "'" + v + "'").join(',') : "''";
const sql = mapeoSel
  ? "SELECT * FROM `inlaid-stack-375114.analytics_data_products.opportunity_mapping` WHERE CAST(nit_emisor AS STRING) = '" + nitEmisor +
    "' AND (cufe IN (" + lista(facturasSel.map(f => f.cufe).filter(Boolean)) + ") OR numero_factura IN (" + lista(facturasSel.map(f => f.numeroFactura).filter(Boolean)) + "))"
  : "SELECT 1 AS sin_mapeo LIMIT 0";
return [{ json: {
  config: CONFIG,
  nombreCliente,
  nombreCarpeta,
  // Regla de Karen: con más de un pagador se crea una subcarpeta por pagador; con uno solo, todo va en la carpeta del cliente.
  pagadores: pagadores.map(p => ({ nit: String(p.nit || '').replace(/\D/g, ''), nombre: limpio(p.razonSocial) || ('NIT ' + p.nit) })),
  cotizacion: b.cotizacion && b.cotizacion.base64 ? b.cotizacion : null,
  mapeo: b.mapeo && b.mapeo.csv ? b.mapeo : null,
  mapeoSel,
  sql
} }];

// Mapeo con la estructura validada por Producto (tranformacion_columnas_mapeo.js de Álvaro, 27-oct-2026).
// Diccionario: columna de ORIGEN (opportunity_mapping) -> columna de DESTINO (hoja mapeo). Para cambiar un nombre, solo se edita aquí.
const MAPA = {
  emisor: 'NOMBRE EMISOR',
  nit_emisor: 'NIT EMISOR',
  pagador: 'NOMBRE PAGADOR',
  nit_pagador: 'NIT PAGADOR',
  numero_factura: 'NUMERO FACTURA',
  fecha_expedicion: 'FECHA EXPEDICIÓN',
  fecha_radicacion: 'FECHA DE RADICACION',
  fecha_vencimiento: 'FECHA VENCIMIENTO',
  fecha_aproximada_de_pago: 'FECHA APROXIMADA DE PAGO',
  forma_pago: 'FORMA PAGO',
  vencimiento_pago: 'VENCIMIENTO DE PAGO',
  valor_bruto: 'VALOR BRUTO',
  descuento: 'DESCUENTO',
  total_iva: 'TOTAL IVA',
  total_rete_iva: 'TOTAL RETE IVA',
  tota_rete_fuente: 'TOTAL RETE FUENTE', // el origen trae el typo "tota_"
  total_rete_ica: 'TOTAL RETE ICA',
  valor_neto: 'VALOR NETO',
  valor_neto_calculado: 'VALOR NETO CALCULADO',
  cufe: 'CUFE',
  prefijo: 'PREFIJO',
  numero_factura_sin_prefijo: 'NUMERO DE FACTURA SIN PREFIJO',
};
// Columnas que NO se mapean (se descartan): estado_cupo_cliente, disponible_cupo
const NUMERICAS = ['valor_bruto', 'descuento', 'total_iva', 'total_rete_iva', 'tota_rete_fuente', 'total_rete_ica', 'valor_neto', 'valor_neto_calculado'];

// Excel (.xlsx) sin librerías: zip sin compresión con una hoja "mapeo".
function crc32(buf) {
  let c, crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) { c = (crc ^ buf[i]) & 0xFF; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; crc = (crc >>> 8) ^ c; }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}
function zip(archivos) {
  const locales = [], centrales = []; let offset = 0;
  for (const [nombre, texto] of archivos) {
    const datos = Buffer.from(texto, 'utf8'), n = Buffer.from(nombre, 'utf8'), crc = crc32(datos);
    const h = Buffer.alloc(30); h.writeUInt32LE(0x04034b50, 0); h.writeUInt16LE(20, 4); h.writeUInt16LE(0x0800, 6); h.writeUInt16LE(0, 8);
    h.writeUInt32LE(0, 10); h.writeUInt32LE(crc, 14); h.writeUInt32LE(datos.length, 18); h.writeUInt32LE(datos.length, 22); h.writeUInt16LE(n.length, 26); h.writeUInt16LE(0, 28);
    const c = Buffer.alloc(46); c.writeUInt32LE(0x02014b50, 0); c.writeUInt16LE(20, 4); c.writeUInt16LE(20, 6); c.writeUInt16LE(0x0800, 8); c.writeUInt16LE(0, 10);
    c.writeUInt32LE(0, 12); c.writeUInt32LE(crc, 16); c.writeUInt32LE(datos.length, 20); c.writeUInt32LE(datos.length, 24); c.writeUInt16LE(n.length, 28);
    c.writeUInt16LE(0, 30); c.writeUInt16LE(0, 32); c.writeUInt16LE(0, 34); c.writeUInt16LE(0, 36); c.writeUInt32LE(0, 38); c.writeUInt32LE(offset, 42);
    locales.push(h, n, datos); centrales.push(c, n); offset += 30 + n.length + datos.length;
  }
  const dir = Buffer.concat(centrales), fin = Buffer.alloc(22);
  fin.writeUInt32LE(0x06054b50, 0); fin.writeUInt16LE(archivos.length, 8); fin.writeUInt16LE(archivos.length, 10); fin.writeUInt32LE(dir.length, 12); fin.writeUInt32LE(offset, 16);
  return Buffer.concat([...locales, dir, fin]);
}
function xlsx(encabezados, filas) {
  const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  const col = (i) => { let s = ''; i++; while (i) { const r = (i - 1) % 26; s = String.fromCharCode(65 + r) + s; i = Math.floor((i - 1) / 26); } return s; };
  const celda = (v, r, c, s) => { const ref = col(c) + r;
    if (typeof v === 'number' && isFinite(v)) return '<c r="' + ref + '"' + (s ? ' s="1"' : '') + '><v>' + v + '</v></c>';
    return '<c r="' + ref + '" t="inlineStr"' + (s ? ' s="1"' : '') + '><is><t xml:space="preserve">' + esc(v) + '</t></is></c>'; };
  const filasXml = [encabezados, ...filas].map((f, r) => '<row r="' + (r + 1) + '">' + f.map((v, c) => celda(v, r + 1, c, r === 0)).join('') + '</row>').join('');
  return zip([
    ['[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>'],
    ['_rels/.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],
    ['xl/workbook.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="mapeo" sheetId="1" r:id="rId1"/></sheets></workbook>'],
    ['xl/_rels/workbook.xml.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'],
    ['xl/styles.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf fontId="0" xfId="0"/><xf fontId="1" xfId="0" applyFont="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'],
    ['xl/worksheets/sheet1.xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>' + filasXml + '</sheetData></worksheet>']
  ]);
}

const n = $('Normalizar solicitud').first().json;
const sel = n.mapeoSel;
if (!sel) return [{ json: { xlsx: null, aviso: 'el panel no envió las facturas seleccionadas' } }];
try {
  const salida = $input.all().map(i => i.json || {});
  const errBQ = salida.find(j => j.error);
  const filasBQ = salida.filter(j => !j.error && (j.cufe || j.numero_factura));
  const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
  const elegidas = [], faltan = [];
  sel.facturas.forEach(f => {
    const r = (f.cufe && filasBQ.find(x => norm(x.cufe) === norm(f.cufe)))
      || filasBQ.find(x => norm(x.numero_factura) === norm(f.numeroFactura) && (!f.nitPagador || String(x.nit_pagador || '').replace(/\D/g, '') === f.nitPagador));
    if (r && !elegidas.includes(r)) elegidas.push(r); else if (!r) faltan.push(f.numeroFactura || f.cufe);
  });
  if (!elegidas.length) {
    const msg = errBQ ? 'BigQuery respondió con error: ' + String(errBQ.error.message || errBQ.error.description || JSON.stringify(errBQ.error)).slice(0, 200)
                      : 'BigQuery no devolvió las facturas seleccionadas';
    return [{ json: { xlsx: null, aviso: msg } }];
  }
  // Misma transformación del script de Álvaro; la fecha aproximada de pago viene del radicador (formato YYYY.MM.DD).
  const filas = elegidas.map(item => Object.keys(MAPA).map(origen => {
    let valor = origen === 'fecha_aproximada_de_pago' ? sel.fechaPago : item[origen];
    if (valor && typeof valor === 'object' && 'value' in valor) valor = valor.value;
    if (typeof valor === 'string') valor = valor.trim();
    if (NUMERICAS.includes(origen) && typeof valor === 'string' && /^-?\d+(\.\d+)?$/.test(valor)) valor = Number(valor);
    return valor ?? '';
  }));
  const fecha = new Date().toLocaleString('sv-SE', { timeZone: 'America/Bogota' }).slice(0, 10);
  const nombre = 'Mapeo ' + n.nombreCliente + ' ' + fecha + '.xlsx';
  return [{ json: {
    xlsx: { nombre, base64: xlsx(Object.values(MAPA), filas).toString('base64') },
    filas: filas.length,
    aviso: faltan.length ? 'no se encontraron en opportunity_mapping: ' + faltan.join(', ') : null
  } }];
} catch (e) {
  return [{ json: { xlsx: null, aviso: 'no se pudo armar el Excel del mapeo (' + e.message + ')' } }];
}

const n = $('Normalizar solicitud').first().json;
const carpeta = $input.first().json;
if (!carpeta.id) {
  return [{ json: { hayError: true, error: 'No se pudo crear la carpeta del cliente: ' + JSON.stringify(carpeta.error || carpeta).slice(0, 300) } }];
}
if (n.pagadores.length <= 1) return [{ json: { sinSubcarpetas: true } }];
return n.pagadores.map(p => ({ json: { crearSubcarpeta: true, nombre: p.nombre, padre: carpeta.id } }));

// Llega por la rama de subcarpetas (una por pagador) o directo si hay un solo pagador.
const n = $('Normalizar solicitud').first().json;
const carpeta = $('Drive: crear carpeta del cliente').first().json;
const items = [];
const subcarpetas = $input.all().map(i => i.json).filter(j => j.id && j.mimeType === 'application/vnd.google-apps.folder');
const errores = $input.all().map(i => i.json).filter(j => j.error).map(j => 'Subcarpeta: ' + JSON.stringify(j.error).slice(0, 200));
const adjuntar = async (nombre, buffer, mime) => {
  const binary = await this.helpers.prepareBinaryData(buffer, nombre, mime);
  items.push({ json: { nombre, padre: carpeta.id }, binary: { data: binary } });
};
if (n.cotizacion) await adjuntar(n.cotizacion.nombre || 'Cotizacion.pdf', Buffer.from(n.cotizacion.base64, 'base64'), 'application/pdf');
else errores.push('El panel no envió el PDF de la cotización.');
// Mapeo de facturas (temporal, reunión 26-oct): Excel con la estructura de Producto.
// Si BigQuery no lo pudo armar, se guarda el CSV básico del panel para no perder la radicación.
const mx = $('Armar mapeo').first().json;
if (mx.xlsx) {
  await adjuntar(mx.xlsx.nombre, Buffer.from(mx.xlsx.base64, 'base64'), 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  if (mx.aviso) errores.push('Mapeo: ' + mx.aviso + '.');
} else {
  errores.push('Mapeo: ' + (mx.aviso || 'sin datos') + '. Se guardó el mapeo básico del panel (CSV).');
  if (n.mapeo) await adjuntar(n.mapeo.nombre || 'Mapeo facturas.csv', Buffer.from(n.mapeo.csv, 'utf8'), 'text/csv');
}
// Se guardan subcarpetas y errores para armar la respuesta al final.
items.forEach(i => { i.json.subcarpetas = subcarpetas.map(s => ({ nombre: s.name, id: s.id, url: s.webViewLink })); i.json.errores = errores; });
if (!items.length) return [{ json: { sinArchivos: true, subcarpetas: subcarpetas.map(s => ({ nombre: s.name, id: s.id, url: s.webViewLink })), errores } }];
return items;

const carpeta = $('Drive: crear carpeta del cliente').first().json;
const previo = $('Preparar archivos').all().map(i => i.json);
const subidos = $input.all().map(i => i.json);
const errores = [...new Set(previo.flatMap(p => p.errores || []))];
subidos.forEach((s, k) => { if (!s.id) errores.push('No se pudo guardar ' + ((previo[k] || {}).nombre || 'un archivo') + ': ' + JSON.stringify(s.error || s).slice(0, 200)); });
return [{ json: {
  ok: true,
  carpeta: { id: carpeta.id, nombre: carpeta.name, url: carpeta.webViewLink },
  subcarpetas: (previo[0] || {}).subcarpetas || [],
  archivos: subidos.filter(s => s.id).map(s => ({ nombre: s.name, url: s.webViewLink })),
  errores
} }];
